struct boss_guldanAI : BossAI
    {
        boss_guldanAI(Creature* creature) : BossAI(creature, DATA_GULDAN) 
        {
            SetCorrectTimers();
            JustReachedHome();
            me->m_CombatDistance = 10;
            _introDone = false;
        }

        int8 currentAdd;
        uint8 addDies;

        bool isEmpowered[3]; // bounds (85%) -> liquid hellfire (70%) -> Eye of guldan (55%)
        uint32 healthForEmpowered[3] {85, 70, 55};

        uint16 eyesOfGuldanCasts, felOfSargerasCasts;
        MySpecialList<uint32> felEfluxTimer, liquidHellfireTimer, eyeOfGuldanTimer, blackHarvestTimer, stormTimer;
        uint32 boundsOfFelTimer;

        Creature* selectedVisual{};
        std::map<ObjectGuid, std::vector<ObjectGuid>> addsBoundsOfFel{};
        std::stack<ObjectGuid> souls{};

        bool can_regenerate_energy;
        uint32 timer_for_energy;

        uint8 phase;

        uint32 healthEvent, healthEventMythic;
        uint32 healthForThirdPhase;
        time_t lastTimeDestroyer = 0;

        bool _introDone;
        bool  isDead = false;

        void Reset() override
        {
            addsBoundsOfFel.clear();

            while (!souls.empty())
                souls.pop();

            _Reset();
            me->RemoveAllAreaObjects();

            currentAdd = -1;
            addDies = 0;

            eyesOfGuldanCasts = 0;
            felOfSargerasCasts = 0;

            healthEvent = 20;
            healthEventMythic = 10;
            isDead = false;
            lastTimeDestroyer = 0;

            if (IsMythicRaid())
                healthForThirdPhase = 50;
            else
                healthForThirdPhase = 40;

            for (uint8 i = 0; i<3; ++i)
                isEmpowered[i] = false;

            can_regenerate_energy = false;
            timer_for_energy = 1000;
            me->SetPower(POWER_ENERGY, 0);

            phase = PHASE_FIRST;

            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_BOUNDS_OF_FEL_TICK);
            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_SOUL_CORROSION);

            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_RESONANT_BARRIER);
            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_TIME_DILATION);
            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_SCATTERING_FIELD);

            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_SHADOWY_GAZE);
            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_PARASITIC_WOUND_DMG);
            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_SHARED_SOUL);
            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_SHARED_SOUL_ABSORB);
            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_DARK_TITAN_SCREEN);
            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_FEL_OF_SARGERAS_AURA);

            me->KillAllDelayedEvents();
            me->SetVisible(true);
            me->SetReactState(REACT_DEFENSIVE);
            me->RemoveFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_NOT_SELECTABLE | UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_NOT_ATTACKABLE_1);

            std::list<AreaTrigger*> list;
            me->GetAreaTriggersWithEntryInRange(list, 12376, ObjectGuid::Empty, 120.0f); // fel of sargeras
            for (auto at : list)
                at->Remove();
        }

        void EnterCombat(Unit* /*who*/) override
        {            
            Talk(SAY_AGGRO);
            _EnterCombat();

            me->CastStop();
            me->RemoveAllAuras();

            me->AddDelayedEvent(12 * MINUTE*IN_MILLISECONDS, [this]() -> void
            {
                if (me->IsAlive() && me->isInCombat())
                    me->CastSpell(me, SPELL_BERSERK);

            });

            if (!IsMythicRaid())
            {
                if (GameObject* go = me->GetMap()->GetGameObject(instance->GetGuidData(statuesVisual[addDies])))
                    go->SetByteValue(GAMEOBJECT_FIELD_BYTES_1, 0, 0); // activate

                if (GameObject* go = me->GetMap()->GetGameObject(instance->GetGuidData(statuesVisual[addDies+1])))
                    go->SetByteValue(GAMEOBJECT_FIELD_BYTES_1, 0, 1); // pre-activate

                me->RemoveAurasDueToSpell(spellsVisualCharging[addDies]);

                if (selectedVisual)
                    selectedVisual->DespawnOrUnsummon();

                selectedVisual = me->SummonCreature(NPC_VISUAL_SELECT, positionsOfStatues[addDies+1]);
                DoCast(spellsVisualCharging[addDies+1]);

                DefaultEvents(PHASE_FIRST);
                me->SetControlled(true, UNIT_STATE_ROOT);
            }
            else
                DefaultEvents(PHASE_SECOND); // start from 2 phase

            if (IsLfrRaid())
                return;

            Map::PlayerList const& PlayerList = me->GetMap()->GetPlayers();
            if (!PlayerList.isEmpty())
                for (auto const& itr : PlayerList)
                    if (Player* player = itr.getSource())
                    {
                        uint32 spellId = 0;
                        switch (player->GetSpecializationRole())
                        {
                        case ROLES_HEALER:
                            spellId = SPELL_SCATTERING_FIELD;
                            break;
                        case ROLES_DPS:
                            spellId = SPELL_TIME_DILATION;
                            break;
                        case ROLES_TANK:
                            spellId = SPELL_RESONANT_BARRIER;
                            break;
                        }

                        if (spellId)
                            player->CastSpell(player, spellId, true);
                    }
        }

        void JustReachedHome() override
        {
            std::list<AreaTrigger*> list;
            me->GetAreaTriggersWithEntryInRange(list, 12376, ObjectGuid::Empty, 120.0f); // fel of sargeras
            for (auto at : list)
                at->Remove();

            me->SetControlled(true, UNIT_STATE_ROOT);

            if (IsMythicRaid())
            {
                for (uint8 i =0; i < 4; ++i)
                {
                    if (GameObject* go = me->GetMap()->GetGameObject(instance->GetGuidData(statuesVisual[i])))
                        go->SetByteValue(GAMEOBJECT_FIELD_BYTES_1, 0, 1); // pre-activate

                    me->AddAura(spellsVisualCharging[i], me);
                }

                DoCast(SPELL_EYE_OF_AMANTHUL_PEREPHASE_TO_2);

                if (GameObject* go = me->GetMap()->GetGameObject(instance->GetGuidData(GO_EYE_OF_AMANTUL)))
                    go->SetByteValue(GAMEOBJECT_FIELD_BYTES_1, 0, 0); // activate
            }
            else
            {
                me->AddAura(SPELL_INTRO_FOCUS_ILLIDAN, me);   
                DoCast(SPELL_INTRO); 

                if (selectedVisual)
                    selectedVisual->DespawnOrUnsummon();

                if (GameObject* go = me->GetMap()->GetGameObject(instance->GetGuidData(statuesVisual[addDies])))
                    go->SetByteValue(GAMEOBJECT_FIELD_BYTES_1, 0, 1); // pre-activate

                selectedVisual = me->SummonCreature(NPC_VISUAL_SELECT, positionsOfStatues[addDies]);

                me->RemoveFlag(UNIT_FIELD_FLAGS_2, UNIT_FLAG2_DISABLE_TURN); // visual
                me->ClearUnitState(UNIT_STATE_CANNOT_TURN); // for correct work
            }

        }

        void JustDied(Unit* /*killer*/) override
        {
            if (!IsMythicRaid())
            {
                _JustDied();
                DoCast(SPELL_DEAD);
                DoCast(SPELL_MOVIE);

                instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_FEL_OF_SARGERAS_AURA);
                std::list<AreaTrigger*> list;
                me->GetAreaTriggersWithEntryInRange(list, 12376, ObjectGuid::Empty, 120.0f); // fel of sargeras
                for (auto at : list)
                    at->Remove();
            }
            else
            {
                me->SetVisible(false);
                // me->RemoveAllAreaObjects();
                me->m_Events.KillAllEvents(false);

                events.Reset();
                summons.DespawnEntry(104526);
                summons.DespawnEntry(NPC_BLACK_SOUL);
                summons.DespawnEntry(NPC_CRYSTALL_OF_ILLIDAN);
            }

            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_BOUNDS_OF_FEL_TICK);
            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_SOUL_CORROSION);
            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_RESONANT_BARRIER);
            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_TIME_DILATION);
            instance->DoRemoveAurasDueToSpellOnPlayers(SPELL_SCATTERING_FIELD);
        }

        void KilledUnit(Unit* who) override
        {
            if (who->IsPlayer() && urand(1, 2) == 1)
                Talk(SAY_KILLED);
        }

        void MoveInLineOfSight(Unit* who) override
        {
            if (who->GetTypeId() == TYPEID_PLAYER && !_introDone && me->IsWithinDistInMap(who, 60.0f))
            {
                _introDone = true;
                if (IsMythicRaid())
                    return;

                me->SetFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_NOT_SELECTABLE | UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_NOT_ATTACKABLE_1);

