struct npc_telarn_solar_collapse_stalker : public ScriptedAI
{
    explicit npc_telarn_solar_collapse_stalker(Creature* creature) : ScriptedAI(creature)
    {
        me->SetReactState(REACT_PASSIVE);
    }

    EventMap events;
    uint8 SolarCount = 0;
    float range = 30.0f;

    void Reset() override {}

    void IsSummonedBy(Unit* owner) override
    {
        events.RescheduleEvent(EVENT_1, 1500); //12c-25y, 12c-20y, 6c-15y, 6c-10y, 6c-5y, 1c-0y
        events.RescheduleEvent(EVENT_2, 15000); //Despawn Event

        me->AddDelayedEvent(100, [this] () -> void
        {
            if (me)
            {
                Position pos;
                for (uint8 i = 1; i <= 12; ++i)
                {
                    pos = me->GetNearPosition(25.0f, 0.523f * i);
                    me->PlayOrphanSpellVisual(pos, 0.0f, { pos.GetPositionX(), pos.GetPositionY(), pos.GetPositionZ() + 0.1f }, 58128, 1.5f, ObjectGuid::Empty, true);
                }
            }
        });
    }

    void SolarCollapse(uint8 idx)
    {
        uint8 count = 1;

        switch (idx)
        {
            case 1:
            case 2:
                count = 12;
                break;
            case 3:
            case 4:
            case 5:
                count = 6;
                break;
            default:
                break;
        }

        Position pos;
        float angle = 6.28 / count;
        range -= 5.0f;

        for (uint8 i = 1; i <= count; ++i)
        {
            pos = me->GetNearPosition(range, angle * i);
            me->CastSpell(pos, SPELL_SOLAR_COLLAPSE_MISSLE_1, true);

            me->AddDelayedEvent(500, [this, idx, pos] () -> void
            {
                if (me && idx == 6) // The last tick has a personal visual
                    me->PlayOrphanSpellVisual(pos, 0.0f, { pos.GetPositionX(), pos.GetPositionY(), pos.GetPositionZ() - 0.1f }, 58170, 1.0f, ObjectGuid::Empty, true);
            });
        }
    }

    void UpdateAI(uint32 diff) override
    {
        events.Update(diff);

        if (uint32 eventId = events.ExecuteEvent())
        {
            switch (eventId)
            {
                case EVENT_1:
                    SolarCollapse(++SolarCount);
                    if (SolarCount < 6)
                        events.RescheduleEvent(EVENT_1, 1000);
                    break;
                case EVENT_2:
                    me->DespawnOrUnsummon();
                    break;
            }
        }
    }
}

