                    Traps();
                    events.RescheduleEvent(EVENT_TRAPS, 16000);
                    break;
                case EVENT_DETONATE_TRAPS:
                    DoCast(me, SPELL_DETONATE_TRAPS, true);
                    events.RescheduleEvent(EVENT_DETONATE_TRAPS, 20000);
