                            if (aiLifetimeGuard.expired()) return;
                            if (Unit* target = SelectTarget(SELECT_TARGET_RANDOM, 0, 100.0f, true, SPELL_GHOSTSTRIKE_MARKED))
                            {
                                DoCast(target, SPELL_CHARGE);
